create trigger collection_test_journey after insert or update of step on private.whatsapp_flow_state for each row execute function private.capture_journey_step();
do $$ declare s uuid:=gen_random_uuid();u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();foreign_v uuid:=gen_random_uuid();c uuid:=gen_random_uuid();d uuid:=gen_random_uuid();p uuid:=gen_random_uuid();w uuid;version integer;request_id uuid:=gen_random_uuid();r jsonb;
begin
 insert into public.stores values(s);insert into public.memberships values(s,u,'owner');insert into public.store_billing values(s,'sandbox','premium','ACTIVE',now()-interval '1 day',now()+interval '1 month');
 insert into public.policy_versions(id,store_id) values(p,s);
 insert into public.eligibility_decisions(id,store_id,policy_version_id,outcome) values(d,s,p,'ELIGIBLE');insert into public.return_cases(id,store_id,status,decision_id,order_id) values(c,s,'OPEN',d,'100');
 insert into public.whatsapp_conversations(id,store_id,return_case_id) values(v,s,c),(foreign_v,s,null);
 w:=public.shipping_register_warehouse(s,'sandbox','COLLECTION-'||s::text);
 version:=public.shipping_settings_save(s,u,0,w,array['2828'],'PICKUP_BY_DC',10000,true);
 version:=public.shipping_settings_approve(s,u,version,repeat('e',64));
 r:=public.shipping_collection_gate(s,v,c);perform public.test_shipping_assert((r->>'allowed')::boolean,'approved eligible gate');
 perform public.test_shipping_reject(format('select public.shipping_collection_gate(%L,%L,%L)',s,foreign_v,c));
 perform public.test_shipping_assert(not has_table_privilege('authenticated','private.shipping_collection_confirmations','select'),'raw address hidden from browser');
 perform public.test_shipping_assert(not has_function_privilege('authenticated','public.shipping_collection_confirm(uuid,uuid,uuid,uuid,integer,text)','execute'),'confirmation service only');
 r:=public.shipping_collection_confirm(s,v,c,request_id,version-1,'v1.YQ==.Yg==');perform public.test_shipping_assert(not (r->>'confirmed')::boolean,'stale settings denied');
 update public.store_billing set plan='standard' where store_id=s;
 perform public.test_shipping_assert(not (public.shipping_collection_gate(s,v,c)->>'allowed')::boolean,'standard denied');update public.store_billing set plan='premium' where store_id=s;
 update public.eligibility_decisions set outcome='MANUAL_REVIEW' where id=d;
 perform public.test_shipping_assert(not (public.shipping_collection_gate(s,v,c)->>'allowed')::boolean,'manual review denied');update public.eligibility_decisions set outcome='ELIGIBLE' where id=d;
 perform public.test_shipping_reject(format('select public.shipping_collection_confirm(%L,%L,%L,%L,%s,''plaintext address'')',s,v,c,request_id,version));
 insert into public.policy_versions(store_id,published_at) values(s,now()+interval '1 second');
 perform public.test_shipping_assert(not (public.shipping_collection_gate(s,v,c)->>'allowed')::boolean,'changed policy needs review');
 delete from public.policy_versions where store_id=s and id<>p;
 update public.return_cases set status='CANCELLED' where public.return_cases.id=c;
 perform public.test_shipping_assert(not (public.shipping_collection_gate(s,v,c)->>'allowed')::boolean,'cancelled return denied');update public.return_cases set status='OPEN' where public.return_cases.id=c;
 update public.store_billing set period_end=now()-interval '1 second' where store_id=s;
 perform public.test_shipping_assert(not (public.shipping_collection_gate(s,v,c)->>'allowed')::boolean,'expired premium denied');update public.store_billing set period_end=now()+interval '1 month' where store_id=s;
 version:=public.shipping_settings_pause(s,u,version);
 perform public.test_shipping_assert(not (public.shipping_collection_gate(s,v,c)->>'allowed')::boolean,'paused authorization denied');
 version:=public.shipping_settings_approve(s,u,version,repeat('e',64));
 r:=public.shipping_collection_confirm(s,v,c,request_id,version,'v1.YQ==.Yg==');perform public.test_shipping_assert((r->>'confirmed')::boolean,'confirmed');
 r:=public.shipping_collection_confirm(s,v,c,request_id,version,'v1.YQ==.Yg==');perform public.test_shipping_assert((select count(*) from private.shipping_collection_confirmations where case_id=c)=1,'exact replay no duplicate');
 insert into private.whatsapp_flow_state values(v,'SHIPPING_COLLECTION','{"collection":{"ciphertext":"v1.private","expiresAt":1}}');
 insert into private.whatsapp_inbox(id,status,message,reply) values('collection-test','PROCESSING','{"id":"collection-test","from":"test","text":{"body":"Private Sample Street"}}',null);
 perform public.commit_whatsapp_transition('collection-test',v,'COMPLETE',jsonb_build_object('caseId',c),'{"plan":{"body":"Your details are saved"}}');
 perform public.test_shipping_assert((select message->'text'->>'body' from private.whatsapp_inbox where id='collection-test')='[Return collection details hidden]','raw input scrubbed with durable reply');
 perform public.test_shipping_assert((select reply is not null from private.whatsapp_inbox where id='collection-test'),'reply remains recoverable');
 update private.shipping_collection_confirmations set expires_at=now()-interval '1 second' where case_id=c;
 update private.whatsapp_flow_state set context='{"collection":{"ciphertext":"encrypted-expired","expiresAt":1},"returnResume":{"context":{"collection":{"ciphertext":"encrypted-expired","expiresAt":1}}}}' where conversation_id=v;
 insert into public.whatsapp_contacts values(u,s,'test-sender');update public.whatsapp_conversations set contact_id=u where public.whatsapp_conversations.id=v;
 insert into private.whatsapp_inbox(id,status,message,sender,created_at) values('collection-failed','PROCESSING','{"id":"collection-failed","text":{"body":"Private Failed Street"}}','test-sender',now()-interval '25 hours');
 perform public.shipping_collection_mark_transport('collection-failed',v);
 update private.whatsapp_inbox set status='FAILED' where private.whatsapp_inbox.id='collection-failed';
 perform public.test_shipping_reject(format('select public.shipping_collection_mark_transport(''collection-failed'',%L)',foreign_v));
 perform public.shipping_collection_purge();
 perform public.test_shipping_assert((select message->'text'->>'body' from private.whatsapp_inbox where private.whatsapp_inbox.id='collection-failed')='[Expired return collection input hidden]','failed transport expires too');
 perform public.test_shipping_assert((select ciphertext is null and state='EXPIRED' from private.shipping_collection_confirmations where case_id=c),'private detail expiry');
 perform public.test_shipping_assert((select not(context?'collection') and not((context#>'{returnResume,context}')?'collection') from private.whatsapp_flow_state where conversation_id=v),'paused draft purge');
 perform public.test_shipping_assert((select count(*) from private.journey_activity where store_id=s and step='COLLECTION_DETAILS_CONFIRMED')=1,'confirmation milestone recorded once without address');
 perform public.test_shipping_assert(not exists(select 1 from private.shipping_attempts where store_id=s),'no booking created');
end $$;
